const raw = $json.data;
const parsed = JSON.parse(raw);

return [
  {
    json: parsed
  }
];

const data = $json;
const documents = [];

for (const epic of data.epics || []) {
  documents.push({
    json: {
      document_id: epic.epic_id,
      type: "epic",
      title: epic.titel,
      text: `Epic: ${epic.titel}\nZiel: ${epic.ziel}\nKategorien: ${(epic.kategorien || []).join(", ")}`,
      source: "tickets.json"
    }
  });

  for (const story of epic.stories || []) {
    const criteriaText = (story.akzeptanzkriterien || [])
      .map((k, i) => `${i + 1}. ${k.text} Messverfahren: ${k.messverfahren}`)
      .join("\n");

    documents.push({
      json: {
        document_id: story.story_id,
        type: "story",
        title: story.titel,
        text: `Story: ${story.titel}\nBeschreibung: ${story.beschreibung}\nAkzeptanzkriterien:\n${criteriaText}`,
        dependencies: story.abhaengigkeiten || [],
        source: "tickets.json"
      }
    });
  }
}

return documents;

const docs = $('Create RAG Documents').all();
const embeddings = $input.all();

const points = embeddings.map((item, index) => {
  const doc = docs[index].json;

  return {
    id: index + 1,
    vector: item.json.embedding,
    payload: {
      document_id: doc.document_id,
      type: doc.type,
      title: doc.title,
      text: doc.text,
      source: doc.source,
      dependencies: doc.dependencies || []
    }
  };
});

return [
  {
    json: {
      points
    }
  }
];

return [
  {
    json: {
      question: "Welche Story beschreibt den HitL-Pruefschritt bei niedriger Konfidenz?"
    }
  }
];

const question = $('Set Test Question').first().json.question;
const results = $json.result || [];

const matches = results.map((result, index) => {
  return {
    rank: index + 1,
    score: result.score,
    document_id: result.payload.document_id,
    title: result.payload.title,
    type: result.payload.type,
    text: result.payload.text,
    source: result.payload.source,
    dependencies: result.payload.dependencies || []
  };
});

const context = matches
  .map(match => {
    return `Quelle ${match.rank}
Titel: ${match.title}
Typ: ${match.type}
Score: ${match.score}
Inhalt:
${match.text}`;
  })
  .join("\n\n---\n\n");

return [
  {
    json: {
      question,
      top_match: matches[0]?.title || null,
      context,
      matches
    }
  }
];

const ragContext = $('Prepare RAG Context').first().json;
const llmAnswer = $json.response;

return [
  {
    json: {
      status: "success",
      workflow: "BC3_TO_BC4_RAG_TICKET_WORKFLOW",
      question: ragContext.question,
      top_match: ragContext.top_match,
      answer: llmAnswer,
      sources: ragContext.matches.map(match => ({
        rank: match.rank,
        score: match.score,
        document_id: match.document_id,
        title: match.title,
        type: match.type,
        source: match.source
      })),
      generated_at: new Date().toISOString()
    }
  }
];

const bc4 = $json;

return [
  {
    json: {
      delivery_id: "bc4-delivery-aurelia-2026-06-12-001",
      workflow: bc4.workflow,
      status: bc4.status,
      environment: "local-docker",
      created_at: bc4.generated_at,
      created_by: "BC4 Autonomous Builder",

      input: {
        source_system: "GitHub",
        repository: "pg-coe-kmu/coe-factory",
        source_file: "contracts/bc3-to-bc4/mock/tickets.json",
        project_short_name: "aurelia",
        schema_version: "3.4",
        gate2_status: "pending"
      },

      rag_pipeline: {
        vector_database: "Qdrant",
        collection: "bc4_tickets",
        embedding_runtime: "Ollama",
        embedding_model: "nomic-embed-text",
        llm_runtime: "Ollama",
        llm_model: "llama3.2:3b",
        documents_indexed: 5,
        retrieval_limit: 3,
        top_score: bc4.sources?.[0]?.score || null
      },

      query: {
        question: bc4.question,
        top_match: {
          title: bc4.top_match,
          document_id: bc4.sources?.[0]?.document_id || null,
          type: bc4.sources?.[0]?.type || null,
          score: bc4.sources?.[0]?.score || null,
          source: bc4.sources?.[0]?.source || null
        }
      },

      bc4_result: {
        summary: "BC4 hat die passende Story anhand des lokalen RAG-Kontexts identifiziert.",
        answer: bc4.answer,
        decision: "story_identified",
        confidence: "high"
      },

      matched_sources: bc4.sources,

      test_report: {
        test_status: "passed",
        tests: [
          {
            name: "GitHub tickets.json can be loaded",
            result: "passed"
          },
          {
            name: "tickets.json can be parsed",
            result: "passed"
          },
          {
            name: "RAG documents can be created",
            result: "passed",
            items_created: 5
          },
          {
            name: "Embeddings can be generated with Ollama",
            result: "passed",
            embedding_model: "nomic-embed-text"
          },
          {
            name: "Documents can be stored in Qdrant",
            result: "passed",
            collection: "bc4_tickets"
          },
          {
            name: "Relevant story can be retrieved by semantic search",
            result: "passed",
            top_match: bc4.top_match
          },
          {
            name: "LLM answer can be generated from RAG context",
            result: "passed",
            llm_model: "llama3.2:3b"
          }
        ]
      },

      platform_handoff: {
        target_context: "Platform & Testing",
        gate: "Gate 3 - UAT & Deployment",
        handoff_status: "ready_for_review",
        next_steps: [
          "Workflow exportieren und in GitHub unter workflows/ ablegen",
          "Mock-Output unter examples/ ablegen",
          "Testing-Team prueft UAT-Faelle",
          "Deployment-Dokumentation in docs/ ergaenzen"
        ]
      },

      compliance: {
        data_processing: "local",
        external_ai_api_used: false,
        human_in_the_loop_required: true,
        ai_act_note: "Lokale RAG-Verarbeitung mit transparenter Quellenangabe und menschlicher Pruefung bei unsicheren Faellen.",
        gdpr_note: "Keine Uebertragung interner Ticketdaten an externe LLM-APIs im lokalen Setup."
      }
    }
  }
];
